import{_ as e,o as t,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"CSR、SSR、SSG 与 ISR","description":"","frontmatter":{"title":"CSR、SSR、SSG 与 ISR","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/core/frameworks/rendering-models.md","filePath":"frontend/guide/core/frameworks/rendering-models.md","lastUpdated":1785242340000}'),l={name:"frontend/guide/core/frameworks/rendering-models.md"};function i(r,a,d,p,h,o){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="csr、ssr、ssg-与-isr" tabindex="-1">CSR、SSR、SSG 与 ISR <a class="header-anchor" href="#csr、ssr、ssg-与-isr" aria-label="Permalink to &quot;CSR、SSR、SSG 与 ISR&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>CSR、SSR、SSG 与 ISR 描述 HTML 在哪里、何时生成，以及生成结果如何复用。它们不是四种互斥框架：同一个应用可以让营销页构建时生成、商品页按周期再生成、账户页按请求渲染，进入页面后再用客户端渲染处理交互和导航。</p><p>本篇建立四种模型的请求链、数据时点、缓存和失效边界。具体项目如何在候选方案间取舍，继续参考“技术决策”模块中的 CSR/SSR、SSG/ISR 文章。</p><h2 id="_1-判断渲染模式的维度" tabindex="-1">1. 判断渲染模式的维度 <a class="header-anchor" href="#_1-判断渲染模式的维度" aria-label="Permalink to &quot;1. 判断渲染模式的维度&quot;">​</a></h2><h3 id="_1-1-html-生成位置" tabindex="-1">1.1 HTML 生成位置 <a class="header-anchor" href="#_1-1-html-生成位置" aria-label="Permalink to &quot;1.1 HTML 生成位置&quot;">​</a></h3><p>HTML 可以在：</p><ul><li>浏览器运行 JavaScript 后生成；</li><li>请求到达服务器时生成；</li><li>构建或发布阶段提前生成；</li><li>缓存过期后由后台或首个请求重新生成。</li></ul><h3 id="_1-2-html-生成时机" tabindex="-1">1.2 HTML 生成时机 <a class="header-anchor" href="#_1-2-html-生成时机" aria-label="Permalink to &quot;1.2 HTML 生成时机&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build time -------- request time -------- browser runtime</span></span>
<span class="line"><span>   SSG/ISR             SSR                   CSR</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>ISR 跨越构建和请求：初始版本在构建时生成，后续版本按再验证规则生成。</p><h3 id="_1-3-数据新鲜度" tabindex="-1">1.3 数据新鲜度 <a class="header-anchor" href="#_1-3-数据新鲜度" aria-label="Permalink to &quot;1.3 数据新鲜度&quot;">​</a></h3><p>页面允许的数据年龄决定能否复用 HTML：</p><table tabindex="0"><thead><tr><th>数据约束</th><th>可能模型</th></tr></thead><tbody><tr><td>内容发布后数小时不变</td><td>SSG</td></tr><tr><td>允许 5 分钟旧内容</td><td>ISR / CDN 缓存 SSR</td></tr><tr><td>每个请求都要读取当前公开数据</td><td>SSR</td></tr><tr><td>必须按当前用户权限返回</td><td>SSR 或 CSR 请求用户 API</td></tr><tr><td>页面骨架公开、进入后实时刷新</td><td>SSG/SSR + CSR</td></tr></tbody></table><h3 id="_1-4-用户差异" tabindex="-1">1.4 用户差异 <a class="header-anchor" href="#_1-4-用户差异" aria-label="Permalink to &quot;1.4 用户差异&quot;">​</a></h3><p>同一 URL 对所有用户相同，适合共享缓存。响应依赖 Cookie、身份、地区或实验组时，缓存键和隐私风险迅速增加。</p><h3 id="_1-5-交互激活" tabindex="-1">1.5 交互激活 <a class="header-anchor" href="#_1-5-交互激活" aria-label="Permalink to &quot;1.5 交互激活&quot;">​</a></h3><p>HTML 是否预生成与交互如何激活是两个问题。SSR/SSG 页面可以：</p><ul><li>完全没有客户端 JavaScript；</li><li>整页 hydration；</li><li>只激活部分 islands；</li><li>导航后转为客户端渲染。</li></ul><h2 id="_2-csr" tabindex="-1">2. CSR <a class="header-anchor" href="#_2-csr" aria-label="Permalink to &quot;2. CSR&quot;">​</a></h2><h3 id="_2-1-请求链" tabindex="-1">2.1 请求链 <a class="header-anchor" href="#_2-1-请求链" aria-label="Permalink to &quot;2.1 请求链&quot;">​</a></h3><p>Client-side Rendering 由浏览器执行应用 JavaScript并生成主要界面：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 -&gt; GET /orders</span></span>
<span class="line"><span>服务器 -&gt; HTML shell</span></span>
<span class="line"><span>浏览器 -&gt; GET app.js</span></span>
<span class="line"><span>浏览器 -&gt; 执行框架、匹配路由</span></span>
<span class="line"><span>浏览器 -&gt; GET /api/orders</span></span>
<span class="line"><span>浏览器 -&gt; render UI</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>初始 HTML 常只有挂载容器、资源链接和少量静态内容。</p><h3 id="_2-2-数据时点" tabindex="-1">2.2 数据时点 <a class="header-anchor" href="#_2-2-数据时点" aria-label="Permalink to &quot;2.2 数据时点&quot;">​</a></h3><p>数据在浏览器运行时获取，天然能读取当前会话和客户端环境。首屏可能产生“HTML -&gt; JS -&gt; API”的串行瀑布。</p><p>元框架或 Router 数据 API 可以提前发现请求，但只要主要内容仍在客户端生成，模型仍属于 CSR。</p><h3 id="_2-3-导航" tabindex="-1">2.3 导航 <a class="header-anchor" href="#_2-3-导航" aria-label="Permalink to &quot;2.3 导航&quot;">​</a></h3><p>首次加载后，客户端 Router 拦截同源导航，更新 URL、请求数据和渲染页面，无需重新下载完整文档。</p><p>应用必须保证：</p><ul><li>刷新任意路由时服务器回退到入口 HTML；</li><li>URL 与状态同步；</li><li>前进后退恢复正确；</li><li>分包加载失败有恢复入口。</li></ul><h3 id="_2-4-缓存" tabindex="-1">2.4 缓存 <a class="header-anchor" href="#_2-4-缓存" aria-label="Permalink to &quot;2.4 缓存&quot;">​</a></h3><p>入口 HTML 通常短缓存或每次验证；带内容哈希的 JS/CSS 长期缓存。API 数据使用独立 HTTP cache 或 server-state cache。</p><h3 id="_2-5-适用边界" tabindex="-1">2.5 适用边界 <a class="header-anchor" href="#_2-5-适用边界" aria-label="Permalink to &quot;2.5 适用边界&quot;">​</a></h3><p>CSR 适合登录后的工作台、编辑器和内部工具等高交互应用。它的主要代价是初始内容依赖 JavaScript 下载与执行，弱设备和高延迟网络更明显。</p><h2 id="_3-ssr" tabindex="-1">3. SSR <a class="header-anchor" href="#_3-ssr" aria-label="Permalink to &quot;3. SSR&quot;">​</a></h2><h3 id="_3-1-请求链" tabindex="-1">3.1 请求链 <a class="header-anchor" href="#_3-1-请求链" aria-label="Permalink to &quot;3.1 请求链&quot;">​</a></h3><p>Server-side Rendering 在每个请求到达时生成 HTML：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 -&gt; GET /products/P-1</span></span>
<span class="line"><span>服务器 -&gt; 匹配路由</span></span>
<span class="line"><span>服务器 -&gt; 查询产品数据</span></span>
<span class="line"><span>服务器 -&gt; renderToHTML()</span></span>
<span class="line"><span>服务器 -&gt; HTML + serialized data</span></span>
<span class="line"><span>浏览器 -&gt; 展示 HTML</span></span>
<span class="line"><span>浏览器 -&gt; 下载 JS 并 hydration</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>最后两步不是 SSR 的必然要求。服务器可以返回普通可交互表单而不 hydration；现代框架应用通常会激活客户端组件。</p><h3 id="_3-2-请求级上下文" tabindex="-1">3.2 请求级上下文 <a class="header-anchor" href="#_3-2-请求级上下文" aria-label="Permalink to &quot;3.2 请求级上下文&quot;">​</a></h3><p>SSR 可以读取：</p><ul><li>URL 与路由参数；</li><li>Cookie 和请求字段；</li><li>当前用户会话；</li><li>地区、语言和实验信息；</li><li>服务端私有 API。</li></ul><p>这些数据只能存在于当前请求作用域。模块单例 store 若被多个请求共享，可能产生跨用户泄漏。</p><h3 id="_3-3-ttfb" tabindex="-1">3.3 TTFB <a class="header-anchor" href="#_3-3-ttfb" aria-label="Permalink to &quot;3.3 TTFB&quot;">​</a></h3><p>服务器要先完成数据与渲染，可能提高首字节等待。并行数据获取、流式输出、边缘部署和响应缓存可以改善，但都需要测量真实链路。</p><h3 id="_3-4-服务器成本" tabindex="-1">3.4 服务器成本 <a class="header-anchor" href="#_3-4-服务器成本" aria-label="Permalink to &quot;3.4 服务器成本&quot;">​</a></h3><p>每个未缓存请求消耗计算与数据源容量。流量峰值会同时放大应用服务、API 和数据库压力。</p><h3 id="_3-5-缓存" tabindex="-1">3.5 缓存 <a class="header-anchor" href="#_3-5-缓存" aria-label="Permalink to &quot;3.5 缓存&quot;">​</a></h3><p>公开 SSR 页面可以在 CDN 或服务端缓存：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, s-maxage=300, stale-while-revalidate=60</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>一旦响应含用户数据，默认使用 <code>private</code> 或 <code>no-store</code>，不能把 Cookie 响应错误放入共享缓存。</p><h2 id="_4-ssg" tabindex="-1">4. SSG <a class="header-anchor" href="#_4-ssg" aria-label="Permalink to &quot;4. SSG&quot;">​</a></h2><h3 id="_4-1-构建链" tabindex="-1">4.1 构建链 <a class="header-anchor" href="#_4-1-构建链" aria-label="Permalink to &quot;4.1 构建链&quot;">​</a></h3><p>Static Site Generation 在构建阶段生成 HTML：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>content / API</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     v</span></span>
<span class="line"><span>build routes -&gt; render HTML -&gt; write files</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>                               v</span></span>
<span class="line"><span>                              CDN</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>请求到达时直接返回已有文件，不执行页面服务端渲染。</p><h3 id="_4-2-数据快照" tabindex="-1">4.2 数据快照 <a class="header-anchor" href="#_4-2-数据快照" aria-label="Permalink to &quot;4.2 数据快照&quot;">​</a></h3><p>HTML 使用构建时数据。源数据改变后，旧页面不会自动更新，直到重新构建并发布。</p><h3 id="_4-3-路径发现" tabindex="-1">4.3 路径发现 <a class="header-anchor" href="#_4-3-路径发现" aria-label="Permalink to &quot;4.3 路径发现&quot;">​</a></h3><p>动态路由需要在构建时知道要生成哪些路径：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/articles/A</span></span>
<span class="line"><span>/articles/B</span></span>
<span class="line"><span>/articles/C</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>百万商品全量构建会造成时间、内存与发布产物压力。</p><h3 id="_4-4-cdn-分发" tabindex="-1">4.4 CDN 分发 <a class="header-anchor" href="#_4-4-cdn-分发" aria-label="Permalink to &quot;4.4 CDN 分发&quot;">​</a></h3><p>静态文件容易部署到全球 CDN，失败面小、TTFB 稳定。内容哈希资源可以长期缓存，HTML 仍要设计更新与回滚策略。</p><h3 id="_4-5-客户端增强" tabindex="-1">4.5 客户端增强 <a class="header-anchor" href="#_4-5-客户端增强" aria-label="Permalink to &quot;4.5 客户端增强&quot;">​</a></h3><p>SSG 只决定初始 HTML 来源。页面仍可以 hydration、加载 islands、请求当前用户数据或进入 SPA 导航。</p><h3 id="_4-6-适用边界" tabindex="-1">4.6 适用边界 <a class="header-anchor" href="#_4-6-适用边界" aria-label="Permalink to &quot;4.6 适用边界&quot;">​</a></h3><p>文档、博客、营销页、版本化帮助中心等内容稳定、路径可枚举的页面适合 SSG。高频变化、无限路径或强个性化页面不适合全部预生成。</p><h2 id="_5-isr" tabindex="-1">5. ISR <a class="header-anchor" href="#_5-isr" aria-label="Permalink to &quot;5. ISR&quot;">​</a></h2><h3 id="_5-1-基本模型" tabindex="-1">5.1 基本模型 <a class="header-anchor" href="#_5-1-基本模型" aria-label="Permalink to &quot;5.1 基本模型&quot;">​</a></h3><p>Incremental Static Regeneration 在静态页面基础上加入按需再生成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已有静态 HTML</span></span>
<span class="line"><span>  -&gt; 在有效期内直接返回</span></span>
<span class="line"><span>  -&gt; 到期后触发重新生成</span></span>
<span class="line"><span>  -&gt; 原子替换缓存版本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>ISR 不是 Web 标准，不同元框架和托管平台对触发、阻塞、区域一致性和错误回退的实现不同。</p><h3 id="_5-2-时间再验证" tabindex="-1">5.2 时间再验证 <a class="header-anchor" href="#_5-2-时间再验证" aria-label="Permalink to &quot;5.2 时间再验证&quot;">​</a></h3><p>页面设置再生成间隔，例如 300 秒。间隔表示“最早何时允许重新生成”，不保证源数据变化后恰好 300 秒全球一致。</p><p>一种常见 stale-while-revalidate 行为：</p><ol><li>到期后的首个请求仍得到旧页面；</li><li>平台后台重新生成；</li><li>成功后后续请求得到新页面；</li><li>失败时继续使用旧页面并重试。</li></ol><p>也有实现会让首个请求等待新结果。</p><h3 id="_5-3-按需失效" tabindex="-1">5.3 按需失效 <a class="header-anchor" href="#_5-3-按需失效" aria-label="Permalink to &quot;5.3 按需失效&quot;">​</a></h3><p>CMS 发布、商品更新等事件可以调用失效接口，按路径或标签触发再生成。事件必须经过鉴权、幂等和重试，不能把公开 URL 变成任意清缓存入口。</p><h3 id="_5-4-未构建路径" tabindex="-1">5.4 未构建路径 <a class="header-anchor" href="#_5-4-未构建路径" aria-label="Permalink to &quot;5.4 未构建路径&quot;">​</a></h3><p>平台可以在第一次访问新路径时：</p><ul><li>返回 404；</li><li>阻塞生成后返回；</li><li>先返回 fallback 再客户端补内容。</li></ul><p>具体语义需要查目标框架，不应把所有行为统称为 ISR。</p><h3 id="_5-5-一致性" tabindex="-1">5.5 一致性 <a class="header-anchor" href="#_5-5-一致性" aria-label="Permalink to &quot;5.5 一致性&quot;">​</a></h3><p>多区域 CDN 可能短时间同时存在旧、新版本。价格、库存、权限等强一致数据不要只依赖 ISR HTML；提交操作始终在服务端重新校验。</p><h3 id="_5-6-适用边界" tabindex="-1">5.6 适用边界 <a class="header-anchor" href="#_5-6-适用边界" aria-label="Permalink to &quot;5.6 适用边界&quot;">​</a></h3><p>商品详情、新闻和内容目录等路径多、允许短暂陈旧、又希望静态分发的页面适合 ISR。</p><h2 id="_6-四种模型对比" tabindex="-1">6. 四种模型对比 <a class="header-anchor" href="#_6-四种模型对比" aria-label="Permalink to &quot;6. 四种模型对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>CSR</th><th>SSR</th><th>SSG</th><th>ISR</th></tr></thead><tbody><tr><td>初始 HTML</td><td>浏览器生成主要内容</td><td>每请求生成</td><td>构建时生成</td><td>构建或请求后缓存生成</td></tr><tr><td>数据时点</td><td>浏览器请求时</td><td>页面请求时</td><td>构建时</td><td>最近一次再生成时</td></tr><tr><td>共享缓存</td><td>Shell 与 API 分开</td><td>取决于用户差异</td><td>容易</td><td>容易，但有失效窗口</td></tr><tr><td>服务端渲染成本</td><td>无页面 SSR</td><td>每未缓存请求</td><td>构建阶段</td><td>再生成请求</td></tr><tr><td>首屏依赖 JS</td><td>主要内容通常依赖</td><td>交互依赖，内容可先见</td><td>交互依赖，内容可先见</td><td>交互依赖，内容可先见</td></tr><tr><td>个性化</td><td>客户端获取</td><td>请求级适合</td><td>不适合写入共享 HTML</td><td>不适合写入共享 HTML</td></tr><tr><td>更新速度</td><td>API 返回即更新</td><td>下次请求</td><td>重新构建发布</td><td>失效/再生成后</td></tr><tr><td>大量路径</td><td>运行时处理</td><td>运行时处理</td><td>构建可能膨胀</td><td>可按需生成</td></tr><tr><td>故障回退</td><td>客户端错误 UI</td><td>请求可能失败</td><td>旧静态文件可继续</td><td>常可保留旧版本</td></tr></tbody></table><p>表格描述模型，不代表只看一列就能选型。真实页面还要考虑设备性能、缓存命中率、数据源容量和交互复杂度。</p><h2 id="_7-混合渲染" tabindex="-1">7. 混合渲染 <a class="header-anchor" href="#_7-混合渲染" aria-label="Permalink to &quot;7. 混合渲染&quot;">​</a></h2><h3 id="_7-1-按路由组合" tabindex="-1">7.1 按路由组合 <a class="header-anchor" href="#_7-1-按路由组合" aria-label="Permalink to &quot;7.1 按路由组合&quot;">​</a></h3><p>一个电商站可以这样分配：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/                      SSG</span></span>
<span class="line"><span>/category/:slug        ISR</span></span>
<span class="line"><span>/product/:id           ISR + CSR inventory</span></span>
<span class="line"><span>/account               SSR private/no-store</span></span>
<span class="line"><span>/admin                  CSR</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_7-2-按区域组合" tabindex="-1">7.2 按区域组合 <a class="header-anchor" href="#_7-2-按区域组合" aria-label="Permalink to &quot;7.2 按区域组合&quot;">​</a></h3><p>同一页面也可以混合：</p><ul><li>商品标题、描述来自 ISR HTML；</li><li>库存进入页面后客户端刷新；</li><li>推荐位由客户端按用户加载；</li><li>购买表单由 hydrated component 处理；</li><li>评论区滚动到可见后再加载。</li></ul><h3 id="_7-3-首次导航与后续导航" tabindex="-1">7.3 首次导航与后续导航 <a class="header-anchor" href="#_7-3-首次导航与后续导航" aria-label="Permalink to &quot;7.3 首次导航与后续导航&quot;">​</a></h3><p>首次访问可能得到 SSR/SSG HTML，hydration 后的站内导航由客户端 Router 处理。调试时要分别验证：</p><ul><li>直接输入 URL；</li><li>页面内点击导航；</li><li>刷新；</li><li>前进后退；</li><li>JavaScript 禁用或加载失败。</li></ul><h3 id="_7-4-route-rules" tabindex="-1">7.4 Route Rules <a class="header-anchor" href="#_7-4-route-rules" aria-label="Permalink to &quot;7.4 Route Rules&quot;">​</a></h3><p>现代元框架通常允许为每条路由声明 prerender、server render、revalidate 或 client-only。规则命中顺序和缓存键是框架具体能力，不能只看页面组件代码推断。</p><h2 id="_8-数据获取" tabindex="-1">8. 数据获取 <a class="header-anchor" href="#_8-数据获取" aria-label="Permalink to &quot;8. 数据获取&quot;">​</a></h2><h3 id="_8-1-避免瀑布" tabindex="-1">8.1 避免瀑布 <a class="header-anchor" href="#_8-1-避免瀑布" aria-label="Permalink to &quot;8.1 避免瀑布&quot;">​</a></h3><p>SSR 若父组件先请求，再渲染子组件后才发现第二个请求，会产生服务端瀑布。先建立路由级数据依赖并并行获取：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>product --------\\</span></span>
<span class="line"><span>reviews ---------&gt; render page</span></span>
<span class="line"><span>recommendations -/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_8-2-共享与请求级缓存" tabindex="-1">8.2 共享与请求级缓存 <a class="header-anchor" href="#_8-2-共享与请求级缓存" aria-label="Permalink to &quot;8.2 共享与请求级缓存&quot;">​</a></h3><p>需要区分：</p><table tabindex="0"><thead><tr><th>缓存</th><th>作用域</th></tr></thead><tbody><tr><td>同一次渲染请求去重</td><td>当前请求</td></tr><tr><td>SSR 页面响应缓存</td><td>路径/变体</td></tr><tr><td>数据 API 缓存</td><td>资源键</td></tr><tr><td>客户端查询缓存</td><td>当前浏览器会话</td></tr><tr><td>构建缓存</td><td>构建任务</td></tr></tbody></table><p>把请求级用户数据放进进程全局缓存会泄漏；把公共 CMS 数据每请求都查又浪费容量。</p><h3 id="_8-3-序列化" tabindex="-1">8.3 序列化 <a class="header-anchor" href="#_8-3-序列化" aria-label="Permalink to &quot;8.3 序列化&quot;">​</a></h3><p>客户端 hydration 需要复用服务端数据时，通常把安全快照写入 HTML。必须处理：</p><ul><li><code>&lt;script&gt;</code> 结束标签和 XSS 转义；</li><li>Date、Map、BigInt 等非 JSON 类型；</li><li>只发送客户端真正需要的字段；</li><li>不发送服务端 token 和内部权限信息；</li><li>版本与失效。</li></ul><h3 id="_8-4-重复请求" tabindex="-1">8.4 重复请求 <a class="header-anchor" href="#_8-4-重复请求" aria-label="Permalink to &quot;8.4 重复请求&quot;">​</a></h3><p>若客户端缓存键或数据结构与服务端不一致，hydration 后会立刻再次请求。使用框架官方数据传输机制或明确 cache hydration 契约。</p><h2 id="_9-缓存与失效" tabindex="-1">9. 缓存与失效 <a class="header-anchor" href="#_9-缓存与失效" aria-label="Permalink to &quot;9. 缓存与失效&quot;">​</a></h2><h3 id="_9-1-html-cache" tabindex="-1">9.1 HTML Cache <a class="header-anchor" href="#_9-1-html-cache" aria-label="Permalink to &quot;9.1 HTML Cache&quot;">​</a></h3><p>HTML 是否可共享取决于响应是否对所有缓存键变体相同。<code>Vary: Cookie</code> 常导致极低命中率，也容易遗漏用户差异；公开页面与用户信息最好拆开。</p><h3 id="_9-2-data-cache" tabindex="-1">9.2 Data Cache <a class="header-anchor" href="#_9-2-data-cache" aria-label="Permalink to &quot;9.2 Data Cache&quot;">​</a></h3><p>页面 HTML 和内部数据缓存可能有不同 TTL。清理页面却没清数据，重新生成仍会得到旧内容。</p><h3 id="_9-3-cdn-cache" tabindex="-1">9.3 CDN Cache <a class="header-anchor" href="#_9-3-cdn-cache" aria-label="Permalink to &quot;9.3 CDN Cache&quot;">​</a></h3><p>边缘缓存可能覆盖源站字段。要明确：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source data -&gt; framework data cache -&gt; rendered HTML cache -&gt; CDN</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>每一层的 key、TTL、purge 和观测字段都要记录。</p><h3 id="_9-4-deploy-cache" tabindex="-1">9.4 Deploy Cache <a class="header-anchor" href="#_9-4-deploy-cache" aria-label="Permalink to &quot;9.4 Deploy Cache&quot;">​</a></h3><p>新版本代码不能安全读取旧版本序列化数据时，要给缓存或 payload 增加版本。滚动发布期间新旧服务器也可能同时响应。</p><h3 id="_9-5-失效事件" tabindex="-1">9.5 失效事件 <a class="header-anchor" href="#_9-5-失效事件" aria-label="Permalink to &quot;9.5 失效事件&quot;">​</a></h3><p>按需失效的完整链：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CMS publish</span></span>
<span class="line"><span>-&gt; signed webhook</span></span>
<span class="line"><span>-&gt; validate content ID/version</span></span>
<span class="line"><span>-&gt; invalidate data tag</span></span>
<span class="line"><span>-&gt; invalidate affected routes</span></span>
<span class="line"><span>-&gt; regenerate</span></span>
<span class="line"><span>-&gt; verify new version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>只调用一次 purge 而没有幂等重试和结果监控，会留下静默旧页面。</p><h2 id="_10-个性化与认证" tabindex="-1">10. 个性化与认证 <a class="header-anchor" href="#_10-个性化与认证" aria-label="Permalink to &quot;10. 个性化与认证&quot;">​</a></h2><h3 id="_10-1-不把用户数据写入公共-html" tabindex="-1">10.1 不把用户数据写入公共 HTML <a class="header-anchor" href="#_10-1-不把用户数据写入公共-html" aria-label="Permalink to &quot;10.1 不把用户数据写入公共 HTML&quot;">​</a></h3><p>SSG/ISR 产物会被多个用户共享，不能包含用户名、权限或订单。公共 HTML 只提供壳和公共内容，用户区域在请求级 SSR 或客户端加载。</p><h3 id="_10-2-ssr-用户响应" tabindex="-1">10.2 SSR 用户响应 <a class="header-anchor" href="#_10-2-ssr-用户响应" aria-label="Permalink to &quot;10.2 SSR 用户响应&quot;">​</a></h3><p>按 Cookie 渲染账户页时：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private, no-store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>服务端仍要在每个数据请求中执行授权，不因页面已完成会话校验就信任客户端参数。</p><h3 id="_10-3-登录态闪烁" tabindex="-1">10.3 登录态闪烁 <a class="header-anchor" href="#_10-3-登录态闪烁" aria-label="Permalink to &quot;10.3 登录态闪烁&quot;">​</a></h3><p>公共 SSG 页面若客户端加载登录态，可能先显示“登录”再变成头像。可以使用中性占位、尽早恢复会话或把顶部区域改为边缘/请求级渲染，但要评估缓存损失。</p><h3 id="_10-4-地区与语言" tabindex="-1">10.4 地区与语言 <a class="header-anchor" href="#_10-4-地区与语言" aria-label="Permalink to &quot;10.4 地区与语言&quot;">​</a></h3><p>路径或子域通常比 Cookie 更适合表示可缓存语言版本：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/zh/products/P-1</span></span>
<span class="line"><span>/en/products/P-1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>地区价格仍要在结算时重新验证。</p><h2 id="_11-seo-与可发现性" tabindex="-1">11. SEO 与可发现性 <a class="header-anchor" href="#_11-seo-与可发现性" aria-label="Permalink to &quot;11. SEO 与可发现性&quot;">​</a></h2><h3 id="_11-1-html-内容" tabindex="-1">11.1 HTML 内容 <a class="header-anchor" href="#_11-1-html-内容" aria-label="Permalink to &quot;11.1 HTML 内容&quot;">​</a></h3><p>SSR/SSG/ISR 能直接返回标题、正文、链接和结构化数据，有利于抓取与分享预览。CSR 也可能被支持 JavaScript 的搜索引擎执行，但存在渲染队列、资源失败和不同爬虫能力差异。</p><h3 id="_11-2-metadata" tabindex="-1">11.2 Metadata <a class="header-anchor" href="#_11-2-metadata" aria-label="Permalink to &quot;11.2 Metadata&quot;">​</a></h3><p>title、description、canonical、Open Graph 和结构化数据应与当前路由和内容版本一致。客户端后改 title 不一定被所有分享抓取器执行。</p><h3 id="_11-3-状态码" tabindex="-1">11.3 状态码 <a class="header-anchor" href="#_11-3-状态码" aria-label="Permalink to &quot;11.3 状态码&quot;">​</a></h3><p>服务端应返回真实 <code>200</code>、<code>301/308</code>、<code>404</code>、<code>410</code>。把所有路径都返回 <code>200</code> HTML shell，再在客户端显示“未找到”，会形成 soft 404。</p><h3 id="_11-4-链接" tabindex="-1">11.4 链接 <a class="header-anchor" href="#_11-4-链接" aria-label="Permalink to &quot;11.4 链接&quot;">​</a></h3><p>可抓取导航使用真实 <code>&lt;a href&gt;</code>。只在 div click 中实现跳转会破坏键盘、复制链接和爬虫发现。</p><h3 id="_11-5-seo-不是-ssr-唯一理由" tabindex="-1">11.5 SEO 不是 SSR 唯一理由 <a class="header-anchor" href="#_11-5-seo-不是-ssr-唯一理由" aria-label="Permalink to &quot;11.5 SEO 不是 SSR 唯一理由&quot;">​</a></h3><p>首屏性能、无脚本可用性、分享预览和缓存架构也会影响选择；同样，SSR 不会自动产生高质量语义 HTML 和 metadata。</p><h2 id="_12-失败与降级" tabindex="-1">12. 失败与降级 <a class="header-anchor" href="#_12-失败与降级" aria-label="Permalink to &quot;12. 失败与降级&quot;">​</a></h2><h3 id="_12-1-csr-资源失败" tabindex="-1">12.1 CSR 资源失败 <a class="header-anchor" href="#_12-1-csr-资源失败" aria-label="Permalink to &quot;12.1 CSR 资源失败&quot;">​</a></h3><p>JavaScript 分包加载失败时，页面可能只有空壳。应提供错误边界、重试和刷新到新部署版本的策略。</p><h3 id="_12-2-ssr-数据失败" tabindex="-1">12.2 SSR 数据失败 <a class="header-anchor" href="#_12-2-ssr-数据失败" aria-label="Permalink to &quot;12.2 SSR 数据失败&quot;">​</a></h3><p>区分：</p><ul><li>页面核心数据失败：返回正确错误状态；</li><li>次要区域失败：渲染局部回退；</li><li>超时：取消下游请求，避免占满资源；</li><li>已提交流后失败：使用框架流式错误边界。</li></ul><h3 id="_12-3-ssg-构建失败" tabindex="-1">12.3 SSG 构建失败 <a class="header-anchor" href="#_12-3-ssg-构建失败" aria-label="Permalink to &quot;12.3 SSG 构建失败&quot;">​</a></h3><p>构建时 API 抖动不应发布半套产物。保留上一成功版本，校验生成页数量与关键路径。</p><h3 id="_12-4-isr-再生成失败" tabindex="-1">12.4 ISR 再生成失败 <a class="header-anchor" href="#_12-4-isr-再生成失败" aria-label="Permalink to &quot;12.4 ISR 再生成失败&quot;">​</a></h3><p>平台通常可以继续服务旧页面，但必须监控陈旧年龄。长期“可用但不更新”比直接报错更难发现。</p><h3 id="_12-5-部署一致性" tabindex="-1">12.5 部署一致性 <a class="header-anchor" href="#_12-5-部署一致性" aria-label="Permalink to &quot;12.5 部署一致性&quot;">​</a></h3><p>HTML 引用的新哈希资源必须已经可访问；旧 HTML 引用的旧资源要在缓存窗口内保留。否则滚动发布会产生 ChunkLoadError。</p><h2 id="_13-测量" tabindex="-1">13. 测量 <a class="header-anchor" href="#_13-测量" aria-label="Permalink to &quot;13. 测量&quot;">​</a></h2><h3 id="_13-1-网络阶段" tabindex="-1">13.1 网络阶段 <a class="header-anchor" href="#_13-1-网络阶段" aria-label="Permalink to &quot;13.1 网络阶段&quot;">​</a></h3><p>测量：</p><ul><li>TTFB；</li><li>HTML 体积；</li><li>JS/CSS 下载；</li><li>API 瀑布；</li><li>CDN 命中；</li><li>再生成耗时。</li></ul><h3 id="_13-2-浏览器阶段" tabindex="-1">13.2 浏览器阶段 <a class="header-anchor" href="#_13-2-浏览器阶段" aria-label="Permalink to &quot;13.2 浏览器阶段&quot;">​</a></h3><p>关注：</p><ul><li>FCP/LCP：主要内容何时出现；</li><li>INP：交互是否及时响应；</li><li>CLS：占位与 hydration 是否导致布局跳动；</li><li>Long Tasks：JS 执行与 hydration 成本。</li></ul><h3 id="_13-3-服务器阶段" tabindex="-1">13.3 服务器阶段 <a class="header-anchor" href="#_13-3-服务器阶段" aria-label="Permalink to &quot;13.3 服务器阶段&quot;">​</a></h3><p>拆分：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>route match</span></span>
<span class="line"><span>-&gt; session</span></span>
<span class="line"><span>-&gt; data fetch</span></span>
<span class="line"><span>-&gt; render</span></span>
<span class="line"><span>-&gt; stream/serialize</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>用 Server-Timing 和 trace 连接浏览器 TTFB 与服务端阶段。</p><h3 id="_13-4-分用户群" tabindex="-1">13.4 分用户群 <a class="header-anchor" href="#_13-4-分用户群" aria-label="Permalink to &quot;13.4 分用户群&quot;">​</a></h3><p>平均值会掩盖慢设备和远地区。至少按路由、地区、设备、缓存命中和新旧访问者分组。</p><h2 id="_14-完整案例-内容与账户站点" tabindex="-1">14. 完整案例：内容与账户站点 <a class="header-anchor" href="#_14-完整案例-内容与账户站点" aria-label="Permalink to &quot;14. 完整案例：内容与账户站点&quot;">​</a></h2><h3 id="_14-1-页面约束" tabindex="-1">14.1 页面约束 <a class="header-anchor" href="#_14-1-页面约束" aria-label="Permalink to &quot;14.1 页面约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>变化频率</th><th>用户差异</th><th>路径规模</th><th>交互</th></tr></thead><tbody><tr><td>首页</td><td>每天数次</td><td>无</td><td>1</td><td>低</td></tr><tr><td>文章详情</td><td>发布后少改</td><td>无</td><td>5 万</td><td>中</td></tr><tr><td>热门榜单</td><td>每分钟</td><td>无</td><td>1</td><td>低</td></tr><tr><td>账户</td><td>实时</td><td>强</td><td>用户级</td><td>高</td></tr><tr><td>编辑器</td><td>实时</td><td>强</td><td>文档级</td><td>很高</td></tr></tbody></table><h3 id="_14-2-填写后的模式" tabindex="-1">14.2 填写后的模式 <a class="header-anchor" href="#_14-2-填写后的模式" aria-label="Permalink to &quot;14.2 填写后的模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>初始模式</th><th>客户端行为</th><th>缓存与失效</th></tr></thead><tbody><tr><td>首页</td><td>SSG</td><td>仅菜单 island</td><td>发布触发全页重建</td></tr><tr><td>文章详情</td><td>ISR</td><td>评论滚动后加载</td><td>1 小时再验证 + CMS 按需失效</td></tr><tr><td>热门榜单</td><td>SSR + CDN</td><td>60 秒客户端刷新</td><td><code>s-maxage=60</code></td></tr><tr><td>账户</td><td>SSR</td><td>hydration 后查询缓存接管</td><td><code>private, no-store</code></td></tr><tr><td>编辑器</td><td>CSR shell</td><td>加载文档与实时连接</td><td>HTML shell 短缓存，数据不共享</td></tr></tbody></table><h3 id="_14-3-文章详情结果流" tabindex="-1">14.3 文章详情结果流 <a class="header-anchor" href="#_14-3-文章详情结果流" aria-label="Permalink to &quot;14.3 文章详情结果流&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首次发布</span></span>
<span class="line"><span>-&gt; CMS webhook</span></span>
<span class="line"><span>-&gt; 生成 /articles/A</span></span>
<span class="line"><span>-&gt; CDN 保存 HTML</span></span>
<span class="line"><span>-&gt; 浏览器展示正文</span></span>
<span class="line"><span>-&gt; 评论区可见后加载</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一小时后首个访问</span></span>
<span class="line"><span>-&gt; 返回旧 HTML</span></span>
<span class="line"><span>-&gt; 后台重新生成</span></span>
<span class="line"><span>-&gt; 原子替换成功</span></span>
<span class="line"><span>-&gt; 后续访问得到新 HTML</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_14-4-验收数据" tabindex="-1">14.4 验收数据 <a class="header-anchor" href="#_14-4-验收数据" aria-label="Permalink to &quot;14.4 验收数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>目标</th></tr></thead><tbody><tr><td>文章 CDN 命中率</td><td>&gt;= 95%</td></tr><tr><td>CMS 发布到新页面可见</td><td>&lt;= 2 分钟</td></tr><tr><td>ISR 再生成失败率</td><td>&lt; 0.1%</td></tr><tr><td>账户响应被共享缓存</td><td>0</td></tr><tr><td>编辑器初始 JS 加载失败恢复</td><td>有可见重试</td></tr></tbody></table><p>这些目标让渲染模式成为可验证架构，而不是缩写偏好。</p><h2 id="_15-常见误区" tabindex="-1">15. 常见误区 <a class="header-anchor" href="#_15-常见误区" aria-label="Permalink to &quot;15. 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确理解</th></tr></thead><tbody><tr><td>SPA 就等于 CSR</td><td>SPA 描述导航体验，首次 HTML 仍可 SSR/SSG</td></tr><tr><td>SSR 页面不需要客户端 JS</td><td>内容可见，但框架交互通常需要 hydration</td></tr><tr><td>SSG 内容永远不变</td><td>可以重新构建或由客户端刷新</td></tr><tr><td>ISR 保证每 N 秒更新</td><td>N 通常是最早再验证间隔</td></tr><tr><td>SSR 天然比 CSR 快</td><td>取决于 TTFB、数据、JS 与设备</td></tr><tr><td>SSR 自动解决 SEO</td><td>仍需语义 HTML、metadata、状态码和链接</td></tr><tr><td>使用 CDN 就能缓存用户 SSR</td><td>个性化响应必须隔离或禁止共享</td></tr><tr><td>项目只能选择一个模式</td><td>现代应用通常按路由和区域混合</td></tr><tr><td>服务端拿到数据后客户端不会重复请求</td><td>需要正确序列化与缓存恢复</td></tr></tbody></table><h2 id="_16-总结" tabindex="-1">16. 总结 <a class="header-anchor" href="#_16-总结" aria-label="Permalink to &quot;16. 总结&quot;">​</a></h2><ul><li>CSR 在浏览器运行时生成主要界面；SSR 按请求生成；SSG 构建时生成；ISR 在静态缓存上按规则再生成。</li><li>渲染模式回答 HTML 的位置和时机，不等于 hydration、SPA 或数据缓存策略。</li><li>数据新鲜度、用户差异、路径规模和服务端容量决定 HTML 能否复用。</li><li>HTML、框架数据、CDN 和客户端查询是不同缓存层，失效必须贯穿完整链路。</li><li>同一项目可以按路由组合 SSG、ISR、SSR 与 CSR，并在同一页面把公共内容与个性化区域拆开。</li><li>用 TTFB、Web Vitals、缓存命中、再生成失败和发布可见时间验证选择。</li></ul><h2 id="_17-参考资料" tabindex="-1">17. 参考资料 <a class="header-anchor" href="#_17-参考资料" aria-label="Permalink to &quot;17. 参考资料&quot;">​</a></h2><ul><li><a href="https://nextjs.org/docs/app/building-your-application/rendering" target="_blank" rel="noreferrer">Next.js：Rendering</a></li><li><a href="https://nextjs.org/docs/app/guides/incremental-static-regeneration" target="_blank" rel="noreferrer">Next.js：Incremental Static Regeneration</a></li><li><a href="https://nuxt.com/docs/guide/concepts/rendering" target="_blank" rel="noreferrer">Nuxt：Rendering Modes</a></li><li><a href="https://docs.astro.build/en/guides/on-demand-rendering/" target="_blank" rel="noreferrer">Astro：On-demand rendering</a></li><li><a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">web.dev：Rendering on the Web</a></li></ul>`,197)])])}const u=e(l,[["render",i]]);export{b as __pageData,u as default};
